#!/usr/bin/env bash
#
# The contract: what a desktop that drives jayos-bluetooth may rely on.
#
#   tools/contract.sh            compare contract/ with what the code says
#   tools/contract.sh --write    rewrite the generated files of contract/
#
# Exit 0: contract/ is what the code says (or was rewritten). 1: it is not,
# and the lines above say which file. 2: could not run -- a source this reads
# is missing -- which is not the same answer as "current".
#
# Three files are made here, from the code and never by hand: a contract
# written by hand beside the code would be a second description of it, and the
# two would drift. verbs.txt from VERBS in src/bin/jayos-bluetooth.rs, ops.txt
# from OPS in src/protocol.rs -- the list the protocol's own tests hold to a
# case per op -- and steps.txt from packaging/steps.sh's dispatch.
#
# files.txt is the other kind: a promise, written by hand, of where the
# package puts things, which JayOS reads to know where the drop-ins and
# BlueZ's main.conf are. Generating it from steps.sh would make it say
# whatever steps.sh did; tests/shell/test-packaging.sh runs `steps.sh
# package` and holds what lands to it instead, both ways. README.md and
# VERSION are written by hand too.

set -uo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
MAIN="$ROOT/src/bin/jayos-bluetooth.rs"
PROTOCOL="$ROOT/src/protocol.rs"
STEPS="$ROOT/packaging/steps.sh"
OUT="$ROOT/contract"

for f in "$MAIN" "$PROTOCOL" "$STEPS"; do
    [[ -r "$f" ]] || { echo "contract not exercised: cannot read ${f#"$ROOT"/}" >&2; exit 2; }
done

WORK="$(mktemp -d "${TMPDIR:-/tmp}/jayos-bluetooth-contract.XXXXXX")" || exit 2
trap 'rm -rf "$WORK"' EXIT

header() { # header <what> <made from>
    printf '# %s\n# Generated by tools/contract.sh from %s; do not edit.\n' "$1" "$2"
}

die() { echo "contract.sh: $*" >&2; exit 1; }

# The string literals of one `const NAME: &[&str] = &[ ... ];`, one a line,
# in their order. Comments are dropped first, so a name in a comment is not
# a verb.
rust_list() { # rust_list <file> <const name>
    sed 's|//.*$||' "$1" | awk -v name="$2" '
        $0 ~ "const " name ": &\\[&str\\] = &\\[" { f = 1 }
        f { line = line $0 }
        f && /\];/ { exit }
        END { print line }
    ' | grep -oE '"[^"]+"' | tr -d '"'
}

generate() { # generate <dir>
    local dir=$1 verbs ops steps
    verbs=$(rust_list "$MAIN" VERBS)
    [[ -n "$verbs" ]] || die "read no VERBS from src/bin/jayos-bluetooth.rs"
    ops=$(rust_list "$PROTOCOL" OPS)
    [[ -n "$ops" ]] || die "read no OPS from src/protocol.rs"
    # The dispatch's arms, `    verb)   step_x "${2:-}" ;;`, with their
    # arguments read off usage(): the one line that says what each takes.
    steps=$(sed -n -E 's/^    ([a-z]+)\)[[:space:]]+step_[a-z]+.*;;$/\1/p' "$STEPS")
    [[ -n "$steps" ]] || die "read no verbs from packaging/steps.sh's dispatch"

    { header "The verbs of jayos-bluetooth, the binary in /usr/bin, in its usage's order." \
          "VERBS in src/bin/jayos-bluetooth.rs"
      printf '%s\n' "$verbs"; } > "$dir/verbs.txt"
    { header "The ops the daemon answers on stdin and on its socket, in the protocol table's order." \
          "OPS in src/protocol.rs"
      printf '%s\n' "$ops"; } > "$dir/ops.txt"
    { header "The verbs of packaging/steps.sh, which JayOS's recipe calls, with their arguments." \
          "packaging/steps.sh's dispatch"
      local v
      while IFS= read -r v; do
          if [[ "$v" == package ]]; then printf 'package <pkgdir>\n'; else printf '%s\n' "$v"; fi
      done <<<"$steps"; } > "$dir/steps.txt"
}

mkdir -p "$WORK/new"
generate "$WORK/new"

if [[ "${1:-}" == --write ]]; then
    cp "$WORK/new"/*.txt "$OUT/" || die "could not write contract/"
    echo "  contract/: verbs.txt, ops.txt and steps.txt rewritten"
    exit 0
fi
[[ -z "${1:-}" ]] || { echo "usage: tools/contract.sh [--write]" >&2; exit 2; }

status=0
for f in "$WORK/new"/*.txt; do
    n=${f##*/}
    if [[ ! -f "$OUT/$n" ]]; then
        echo "  contract/$n is missing; tools/contract.sh --write makes it"
        status=1
    elif ! cmp -s "$f" "$OUT/$n"; then
        echo "  contract/$n is not what the code says:"
        diff "$OUT/$n" "$f" | sed 's/^/    /'
        status=1
    fi
done
for f in README.md VERSION files.txt; do
    [[ -f "$OUT/$f" ]] || { echo "  contract/$f, written by hand, is missing"; status=1; }
done
(( status == 0 )) && echo "  contract/ is what the code says"
exit "$status"
